const chartState={id:'soil',year:2020,selection:null,limit:8}
const chartColors={positive:'#285f9b',negative:'#94bde0',grid:'#dce5ee',ink:'#20384e'}
function saveFile(text,name,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function chartCases(){return [...(state.charts?.cases||[]),{id:'revision-counts',title:'Revision impacts by integration process',source:'S1_artC.zip / E1 execution records',unit:'outputs',years:[],scope:'Counts describe the tested revisions. They do not estimate the frequency of errors in the source publications.'}]}
function selectedChart(){const c=chartCases().find(c=>c.id===chartState.id)||chartCases()[0];const year=c.years.includes(Number(chartState.year))?Number(chartState.year):c.default_year;chartState.year=year;let rows=c.id==='revision-counts'?state.evidence.revisions.flatMap(r=>[{key:r.id+'-changed',label:r.pipeline+' / '+r.name,series:'Changed',value:r.changed,status:'available'},{key:r.id+'-flagged',label:r.pipeline+' / '+r.name,series:'Flagged',value:r.flagged,status:'available'},{key:r.id+'-orphans',label:r.pipeline+' / '+r.name,series:'Orphan',value:r.orphans,status:'available'}]):c.data[String(year)];if(c.id==='soil')rows=[...rows].sort((a,b)=>(b.value??-Infinity)-(a.value??-Infinity));if(c.id==='cover'){rows=[...rows].sort((a,b)=>Math.abs(b.value??0)-Math.abs(a.value??0));if(chartState.limit!==0)rows=rows.slice(0,chartState.limit)}return {...c,year,rows,period:year?String(year):'Archive scenarios',versionText:c.versions?c.versions[c.before_version]+' → '+c.versions[c.after_version]:c.id==='noaa'?'Downloaded snapshot / 16 November 2026':'Source versions listed in the execution records'}}
function plotSVG(c){
 const rows=c.rows,W=1080,L=c.id==='revision-counts'?430:220,R=130,T=145,B=110,isLine=c.id==='noaa',H=isLine?580:T+rows.length*29+B;
 let content=`<rect width="${W}" height="${H}" fill="white"/><g font-family="Arial, sans-serif" fill="${chartColors.ink}"><text x="28" y="35" font-size="22" font-weight="bold">${esc(c.title)}</text><text x="28" y="62" font-size="14">${esc(c.versionText)}</text><text x="28" y="85" font-size="14">Period: ${esc(c.period)} · ${isLine?'Concentration':c.id==='revision-counts'?'Output count':'Change'} (${esc(c.unit)})</text>`;
 if(isLine){
  const vals=rows.filter(r=>r.value!=null).map(r=>r.value),lo=Math.floor(Math.min(...vals)-1),hi=Math.ceil(Math.max(...vals)+1),left=90,right=1010,top=130,bottom=440;
  const x=m=>left+(Number(m)-1)/11*(right-left),y=v=>bottom-(v-lo)/(hi-lo)*(bottom-top);
  for(let i=0;i<=4;i++){const v=lo+(hi-lo)*i/4;content+=`<path d="M${left} ${y(v)}H${right}" stroke="${chartColors.grid}"/><text x="${left-12}" y="${y(v)+5}" text-anchor="end" font-size="13">${v.toFixed(1)}</text>`}
  for(let m=1;m<=12;m++)content+=`<text x="${x(m)}" y="465" text-anchor="middle" font-size="13">${String(m).padStart(2,'0')}</text>`;
  [...new Set(rows.map(r=>r.series))].forEach((s,i)=>{const color=i?'#5589b3':'#163d6d',rs=rows.filter(r=>r.series===s);let previous=null;for(const r of rs){if(r.value==null){previous=null;continue}if(previous)content+=`<path d="M${x(previous.label)} ${y(previous.value)}L${x(r.label)} ${y(r.value)}" stroke="${color}" fill="none" stroke-width="2.5" ${i?'stroke-dasharray="7 4"':''}/>`;content+=`<circle cx="${x(r.label)}" cy="${y(r.value)}" r="3.5" fill="${color}"><title>${esc(s)} / ${esc(r.key)}: ${r.value} ppm</title></circle>`;previous=r}content+=`<rect x="${95+i*310}" y="495" width="20" height="4" fill="${color}"/><text x="${125+i*310}" y="502" font-size="14">${esc(s)}</text>`});
 }else{
  const values=rows.filter(r=>r.value!=null).map(r=>r.value),lo=Math.min(0,...values),hi=Math.max(0,...values),span=hi-lo||1,plotWidth=W-L-R,x=v=>L+(v-lo)/span*plotWidth,zero=x(0);
  for(let i=0;i<=4;i++){let v=lo+span*i/4;content+=`<path d="M${x(v)} ${T-22}V${H-B+8}" stroke="${chartColors.grid}"/><text x="${x(v)}" y="${T-35}" text-anchor="middle" font-size="12">${Number(v.toFixed(1)).toLocaleString('en-US')}</text>`}
  content+=`<path d="M${zero} ${T-22}V${H-B+8}" stroke="#4e6983"/>`;
  rows.forEach((r,i)=>{const y=T+i*29,label=r.series?r.label+' / '+r.series:r.label;content+=`<text x="${L-12}" y="${y+4}" text-anchor="end" font-size="13">${esc(label)}</text>`;if(r.value==null){content+=`<text x="${zero+8}" y="${y+4}" font-size="12">${esc(r.status)}</text>`;return}const end=x(r.value);content+=`<rect x="${Math.min(zero,end)}" y="${y-9}" width="${Math.max(.5,Math.abs(end-zero))}" height="17" fill="${r.value<0?chartColors.negative:chartColors.positive}"><title>${esc(label)}: ${r.value} ${esc(c.unit)}</title></rect><text x="${W-20}" y="${y+4}" text-anchor="end" font-size="12">${r.value.toLocaleString('en-US',{maximumFractionDigits:2})}${c.unit==='%'?'%':''}</text>`});
 }
 content+=`<text x="28" y="${H-58}" font-size="12">Source: ${esc(c.source)}${c.id==='cover'&&c.rows.length===8?' · Eight classes with the largest absolute changes':''}</text><text x="28" y="${H-34}" font-size="12">${c.id==='soil'?'Relative change = 100 × (new stock / previous stock − 1).':c.id==='cover'?'Stock difference = new stock − previous stock. Values include changes in mapped contexts.':c.id==='noaa'?'Month is shown on the horizontal axis. Spatial supports differ between the series.':'Each row retains its integration process and source revision.'}</text><text x="28" y="${H-12}" font-size="11">Carbon Provenance Lab · ${c.id==='soil'&&c.year===2020?'Article figure 4':c.id==='cover'&&c.year===2021?'Article figure 5':'Evaluation record'}</text></g>`;
 return `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(c.title)}"><title>${esc(c.title)}</title><metadata>${esc(JSON.stringify({source:c.source,period:c.period,unit:c.unit,versions:c.versionText}))}</metadata>${content}</svg>`
}
function chartCSV(c){const columns=['key','label','series','before','after','value','status','unit'];const quote=x=>'"'+String(x??'').replaceAll('"','""')+'"';return columns.join(',')+'\r\n'+c.rows.map(r=>columns.map(k=>quote(k==='unit'?c.unit:r[k])).join(',')).join('\r\n')+'\r\n'}
function chartsPage(){const c=selectedChart();return heading('Data and revision records','Evaluation workspace','Choose a source case, inspect the values and export the figure with its data.')+`<div class="workspace"><aside class="caseindex"><h2>Source cases</h2>${chartCases().map(x=>`<button class="casechoice ${x.id===c.id?'selected':''}" data-chartcase="${x.id}"><strong>${esc(x.id==='soil'?'MapBiomas / soil':x.id==='cover'?'MapBiomas / land cover':x.id==='noaa'?'NOAA / CO2':'P1, P2 and P3 / revisions')}</strong><span>${esc(x.title)}</span></button>`).join('')}<p class="sub">The source cases retain their units and comparison scope. Data are read from the replication extracts and the NOAA test records.</p><button class="btn" id="chartInspect">Inspect source records</button></aside><section class="chartwork"><div class="chartcontrols"><label for="chartYear">Period</label>${c.years.length?`<select id="chartYear">${c.years.map(y=>`<option ${y===c.year?'selected':''}>${y}</option>`).join('')}</select>`:'<span>Archive scenarios</span>'}${c.id==='cover'?`<label for="classLimit">Classes</label><select id="classLimit"><option value="8" ${chartState.limit===8?'selected':''}>Eight largest changes</option><option value="0" ${chartState.limit===0?'selected':''}>All classes</option></select>`:''}<div class="actions"><button class="btn" id="chartSVG">Export SVG</button><button class="btn" id="chartCSV">Export CSV</button><button class="btn" id="chartRecord">Export record</button><button class="btn" id="chartPDF">Print or save PDF</button></div></div><div id="figureArea">${plotSVG(c)}</div><p class="scope">${esc(c.scope)}</p><details class="chartdata" open><summary>Values used in this figure</summary><p class="sub">Available indicates that the plotting record has a value. It is not a contract validation status.</p><p class="sub">${c.id==='soil'||c.id==='cover'?'Previous and new stock columns use Tg C. The change column uses the unit indicated in the figure. Absent class contexts contribute zero to the corresponding stock total. This convention does not apply to blocked or orphan values.':'Values retain the unit of this case. Missing results are shown by status.'}</p><div class="tablewrap"><table><thead><tr><th>RECORD</th>${c.id==='noaa'||c.id==='revision-counts'?'<th>SERIES</th>':'<th>PREVIOUS STOCK</th><th>NEW STOCK</th>'}<th>${c.id==='noaa'?'VALUE':'CHANGE / COUNT'} (${esc(c.unit)})</th><th>STATUS</th></tr></thead><tbody>${c.rows.map(r=>`<tr><td>${esc(r.label)}</td>${r.series?`<td>${esc(r.series)}</td>`:`<td class="num">${num(r.before)}</td><td class="num">${num(r.after)}</td>`}<td class="num">${num(r.value)}</td><td>${badge(r.status)}</td></tr>`).join('')}</tbody></table></div></details><details class="chartdata"><summary>Source versions and calculation record</summary><pre>${pretty({source:c.source,period:c.period,unit:c.unit,before:c.before_version,after:c.after_version,versions:c.versions,source_hashes:c.id==='noaa'?state.charts.noaa_sources:state.charts.sources,scope:c.scope})}</pre></details></section></div>`}
function bindCharts(){if(state.page!=='overview')return;document.querySelectorAll('[data-chartcase]').forEach(b=>b.onclick=()=>{chartState.id=b.dataset.chartcase;chartState.year=null;render()});if($('#chartYear'))$('#chartYear').onchange=e=>{chartState.year=Number(e.target.value);render()};if($('#classLimit'))$('#classLimit').onchange=e=>{chartState.limit=Number(e.target.value);render()};const c=selectedChart(),stem='carbon-'+c.id+'-'+(c.year||'archive');$('#chartSVG').onclick=()=>saveFile(plotSVG(c),stem+'.svg','image/svg+xml');$('#chartCSV').onclick=()=>saveFile(chartCSV(c),stem+'.csv','text/csv;charset=utf-8');$('#chartRecord').onclick=()=>download({...c,source_hashes:c.id==='noaa'?state.charts.noaa_sources:state.charts.sources},stem+'.json');$('#chartPDF').onclick=()=>window.print();$('#chartInspect').onclick=async()=>{if(c.id==='noaa'){state.result=await fetch('external-noaa-result.json').then(r=>r.json());state.result.origin='transfer_execution';state.query='concentration_difference|2020|01';state.selected=state.query;state.status='all';go('values')}else{state.filter=c.id==='revision-counts'?'all':'P3';go('revisions')}}}
